#!/usr/bin/env python3
import socket, time
path = "/tmp/alpine.sock"
out = open("/app/serial.log", "ab", buffering=0)
while True:
    try:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.connect(path)
        s.settimeout(1)
        out.write(b"\n=== connected ===\n")
        while True:
            try:
                d = s.recv(65536)
                if not d:
                    break
                out.write(d)
            except socket.timeout:
                pass
    except Exception as e:
        out.write(("=== reconnect: %s ===\n" % e).encode())
        time.sleep(1)

